import java.text.Normalizer;
import java.util.Arrays;
import java.util.Collection;
import java.util.List;
import java.util.Locale;
import java.util.Objects;
import java.util.Set;

/**
 * The criteria a customer must satisfy to be listed.
 *
 * <p>A customer matches when it satisfies both parts. Every name term must be
 * found, ignoring case and accents, in the customer's first name or last name.
 * And if any statuses are given, the customer must have one of them.
 *
 * @param nameTerms normalised, non-empty terms that the name must contain;
 *                  empty matches every name
 * @param statuses  statuses to accept; empty accepts every status
 */
public record CustomerFilter(List<String> nameTerms, Set<CustomerStatus> statuses) {

    /** Matches every customer. */
    public static final CustomerFilter NONE = new CustomerFilter(List.of(), Set.of());

    public CustomerFilter {
        nameTerms = List.copyOf(nameTerms);
        statuses = Set.copyOf(statuses);
    }

    /**
     * Builds a filter from the raw name text and the selected statuses.
     *
     * @param name     the text typed by the user; split on whitespace into terms
     * @param statuses the statuses to accept; empty for all of them
     */
    public static CustomerFilter of(String name, Collection<CustomerStatus> statuses) {
        List<String> terms = Arrays.stream(normalize(Objects.requireNonNullElse(name, "")).split("\\s+"))
                .filter(term -> !term.isEmpty())
                .toList();
        return new CustomerFilter(terms, Set.copyOf(statuses));
    }

    /** Returns {@code true} if the customer satisfies both parts of this filter. */
    public boolean matches(Customer customer) {
        if (!statuses.isEmpty() && !statuses.contains(customer.status())) {
            return false;
        }
        String firstName = normalize(customer.firstName());
        String lastName = normalize(customer.lastName());
        return nameTerms.stream()
                .allMatch(term -> firstName.contains(term) || lastName.contains(term));
    }

    /** Lower-cases the text and strips accents, so that comparisons ignore both. */
    private static String normalize(String text) {
        return Normalizer.normalize(text, Normalizer.Form.NFD)
                .replaceAll("\\p{M}+", "")
                .toLowerCase(Locale.ROOT);
    }
}
